import{_ as l,a0 as a,w as p,s as i,I as s,x as t,a1 as e,A as r,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具 | LCTT x X-CMD","titleTemplate":false,"description":"安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux","title":"安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具","tag":"201508","desc":""},"relativePath":"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux.md","filePath":"[post].md"}'),u={name:"201508/20150205 Install Strongswan - A Tool to Setup IPsec Based VPN in Linux.md"};function d(w,n,m,c,x,P){const o=a("Link");return p(),i("div",null,[n[15]||(n[15]=s("h1",{id:"安裝-strongswan-linux-上一個基於-ipsec-的-vpn-工具",tabindex:"-1"},[t("安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具 "),s("a",{class:"header-anchor",href:"#安裝-strongswan-linux-上一個基於-ipsec-的-vpn-工具","aria-label":"Permalink to “安裝 Strongswan ：Linux 上一個基於 IPsec 的 VPN 工具”"},"​")],-1)),n[16]||(n[16]=s("p",null,"IPsec是一個提供網絡層安全的標準。它包含認證頭(AH)和安全負載封裝(ESP)組件。AH提供包的完整性，ESP組件提供包的保密性。IPsec確保了在網絡層的安全特性。",-1)),n[17]||(n[17]=s("ul",null,[s("li",null,"保密性"),s("li",null,"數據包完整性"),s("li",null,"來源不可抵賴性"),s("li",null,"重放攻擊防護")],-1)),s("p",null,[e(o,{href:"https://www.strongswan.org/"},{default:r(()=>[...n[0]||(n[0]=[t("Strongswan",-1)])]),_:1}),n[1]||(n[1]=t("是一個IPsec協議的開源代碼實現，Strongswan的意思是強安全廣域網（StrongS/WAN）。它支持IPsec的VPN中的兩個版本的密鑰自動交換（網絡密鑰交換（IKE）V1和V2）。",-1))]),n[18]||(n[18]=g(`<p>Strongswan基本上提供了在VPN的兩個節點/網關之間自動交換密鑰的共享，然後它使用了Linux內核的IPsec（AH和ESP）實現。密鑰共享使用了之後用於ESP數據加密的IKE 機制。在IKE階段，strongswan使用OpenSSL的加密算法（AES，SHA等等）和其他加密類庫。無論如何，IPsec中的ESP組件使用的安全算法是由Linux內核實現的。Strongswan的主要特性如下：</p><ul><li>x.509證書或基於預共享密鑰認證</li><li>支持IKEv1和IKEv2密鑰交換協議</li><li>可選的，對於插件和庫的內置完整性和加密測試</li><li>支持橢圓曲線DH羣和ECDSA證書</li><li>在智能卡上存儲RSA私鑰和證書</li></ul><p>它能被使用在客户端/服務器（road warrior模式）和網關到網關的情景。</p><h3 id="如何安裝" tabindex="-1">如何安裝 <a class="header-anchor" href="#如何安裝" aria-label="Permalink to “如何安裝”">​</a></h3><p>幾乎所有的Linux發行版都支持Strongswan的二進制包。在這個教程，我們會從二進制包安裝strongswan，也會從源代碼編譯帶有合適的特性的strongswan。</p><h3 id="使用二進制包" tabindex="-1">使用二進制包 <a class="header-anchor" href="#使用二進制包" aria-label="Permalink to “使用二進制包”">​</a></h3><p>可以使用以下命令安裝Strongswan到Ubuntu 14.04 LTS</p><pre><code>$ sudo aptitude install strongswan
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strongswan-binary.png" alt="安裝strongswan"></p><p>strongswan的全局配置（strongswan.conf）文件和ipsec配置（ipsec.conf/ipsec.secrets）文件都在/etc/目錄下。</p><h3 id="strongswan源碼編譯安裝的依賴包" tabindex="-1">strongswan源碼編譯安裝的依賴包 <a class="header-anchor" href="#strongswan源碼編譯安裝的依賴包" aria-label="Permalink to “strongswan源碼編譯安裝的依賴包”">​</a></h3><ul><li>GMP（strongswan使用的高精度數學庫）</li><li>OpenSSL（加密算法來自這個庫）</li><li>PKCS（1，7，8，11，12）（證書編碼和智能卡集成）</li></ul><h4 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to “步驟”">​</a></h4><p><strong>1)</strong> 在終端使用下面命令到/usr/src/目錄</p><pre><code>$ cd /usr/src
</code></pre><p><strong>2)</strong> 用下面命令從strongswan網站下載源代碼</p><pre><code> $ sudo wget http://download.strongswan.org/strongswan-5.2.1.tar.gz
</code></pre><p>（strongswan-5.2.1.tar.gz 是當前最新版。）</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/download_strongswan.png" alt="下載軟件"></p><p><strong>3)</strong> 用下面命令提取下載的軟件，然後進入目錄。</p><pre><code>$ sudo tar –xvzf strongswan-5.2.1.tar.gz; cd strongswan-5.2.1
</code></pre><p><strong>4)</strong> 使用configure命令配置strongswan每個想要的選項。</p><pre><code>$ ./configure --prefix=/usr/local -–enable-pkcs11 -–enable-openssl
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/strongswan-configure.png" alt="檢查strongswan包"></p><p>如果GMP庫沒有安裝，配置腳本將會發生下面的錯誤。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-error.png" alt="GMP library error"></p><p>因此，首先，使用下面命令安裝GMP庫然後執行配置腳本。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-installation1.png" alt="gmp installation"></p><p>不過，如果GMP已經安裝還報上述錯誤的話，在Ubuntu上使用如下命令，給在路徑 /usr/lib，/lib/，/usr/lib/x86_64-linux-gnu/ 下的libgmp.so庫創建軟連接。</p><pre><code>$ sudo ln -s /usr/lib/x86_64-linux-gnu/libgmp.so.10.1.3 /usr/lib/x86_64-linux-gnu/libgmp.so
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/softlink.png" alt="softlink of libgmp.so library"></p><p>創建libgmp.so軟連接後，再執行./configure腳本也許就找到gmp庫了。然而，如果gmp頭文件發生其他錯誤，像下面這樣。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-header.png" alt="GMP header file issu"></p><p>為解決上面的錯誤，使用下面命令安裝libgmp-dev包</p><pre><code>$ sudo aptitude install libgmp-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/gmp-dev.png" alt="Installation of Development library of GMP"></p><p>安裝gmp的開發庫後，在運行一遍配置腳本，如果沒有發生錯誤，則將看見下面的這些輸出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/12/successful-run.png" alt="Output of Configure scirpt"></p><p>使用下面的命令編譯安裝strongswan。</p><pre><code>$ sudo make ; sudo make install 
</code></pre><p>安裝strongswan後，全局配置（strongswan.conf）和ipsec策略/密碼配置文件（ipsec.conf/ipsec.secretes）被放在<strong>/usr/local/etc</strong>目錄。</p><p>根據我們的安全需要Strongswan可以用作隧道或者傳輸模式。它提供眾所周知的site-2-site模式和road warrior模式的VPN。它很容易使用在Cisco，Juniper設備上。</p><hr>`,43)),s("p",null,[n[3]||(n[3]=t("via: ",-1)),e(o,{href:"http://linoxide.com/security/install-strongswan/"},{default:r(()=>[...n[2]||(n[2]=[t("http://linoxide.com/security/install-strongswan/",-1)])]),_:1})]),s("p",null,[n[7]||(n[7]=t("作者：",-1)),e(o,{href:"http://linoxide.com/author/naveeda/"},{default:r(()=>[...n[4]||(n[4]=[t("nido",-1)])]),_:1}),n[8]||(n[8]=t(" 譯者：",-1)),e(o,{href:"https://github.com/wyangsun"},{default:r(()=>[...n[5]||(n[5]=[t("wyangsun",-1)])]),_:1}),n[9]||(n[9]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:r(()=>[...n[6]||(n[6]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[12]||(n[12]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[10]||(n[10]=[t("LCTT",-1)])]),_:1}),n[13]||(n[13]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:r(()=>[...n[11]||(n[11]=[t("Linux中國",-1)])]),_:1}),n[14]||(n[14]=t(" 榮譽推出",-1))])])}const I=l(u,[["render",d]]);export{b as __pageData,I as default};
